namespace Harborline.Foundation.RuleEngine;

/// <summary>
/// Stable, locale-independent diagnostic codes emitted by the rule engine
/// (SPINE-1 design §2.3, §4). Codes are the cross-tier contract — the TS engine
/// emits the identical strings; clients localize off these, never off prose.
/// </summary>
public static class RuleEngineCodes
{
    // ── Runtime evaluation errors (become a ComputedValue.Error / Validity.Error) ──

    /// <summary>Division (or modulo) by zero.</summary>
    public const string DivByZero = "rule.div_by_zero";

    /// <summary>An operand had the wrong type for the operator.</summary>
    public const string TypeError = "rule.type_error";

    /// <summary>A referenced cell is itself in <c>Error</c> — the error propagates.</summary>
    public const string UpstreamError = "rule.upstream_error";

    /// <summary>An unknown / non-whitelisted operator appeared in a lowered AST.</summary>
    public const string UnknownOperator = "rule.unknown_operator";

    /// <summary>A <c>var</c> / <c>agg</c> reference could not be resolved against the instance.</summary>
    public const string BadReference = "rule.bad_reference";

    /// <summary>A per-row cycle was detected defensively at instance time (SPINE-1 §2.3).</summary>
    public const string Cycle = "rule.cycle";

    /// <summary>The per-instance evaluation step budget was exhausted (SPINE-1 §4).</summary>
    public const string BudgetExceeded = "rule.budget_exceeded";

    /// <summary>The per-evaluation wall-clock ceiling (or a cancellation token) tripped (SPINE-1 §4).
    /// This is the code carried by <see cref="RuleEngineTimeoutException"/> — a non-authoritative
    /// infrastructure fault that PROPAGATES; it is never emitted as an evaluation outcome, so the
    /// wall-clock cannot cause a cross-tier divergent result (D1 ratification 2026-07-01).</summary>
    public const string Timeout = "rule.timeout";

    /// <summary>The instance graph exceeded the max-node bound (SPINE-1 §4).</summary>
    public const string GraphTooLarge = "rule.graph_too_large";

    /// <summary>A child table feeding an aggregate exceeded the max-row bound (SPINE-1 §4).</summary>
    public const string TableTooLarge = "rule.table_too_large";

    /// <summary>A <c>Pending</c> value reached the synchronous .NET integrity tier at save
    /// (SPINE-1 §1.3, Decision DE) — fail-closed.</summary>
    public const string PendingAtSave = "rule.pending_at_save";

    /// <summary>A numeric aggregate (<c>avg</c>) over a money / decimal-string column is
    /// not exact in v1 — decimal division is undefined — so it fails closed (finding F7).</summary>
    public const string MoneyAggUnsupported = "rule.money_agg_unsupported";

    /// <summary>A <c>Compute</c> rule was scoped to <c>Section</c>/<c>Schema</c> in a form graph,
    /// where it addresses no value cell — fail closed instead of a silent no-op (finding F8).</summary>
    public const string ComputeScopeInvalid = "rule.compute_scope_invalid";

    /// <summary>A <c>set-options</c> (Options) rule's expression evaluated to a non-array value —
    /// options must be a JSON array; fail closed instead of coercing (ADR 0146 D2 Wave-1).</summary>
    public const string OptionsNotArray = "rule.options_not_array";

    /// <summary>An effectful adapter was offered to the pure evaluator instead of a captured snapshot.</summary>
    public const string ContextSnapshotRequired = "rule.context_snapshot_required";

    /// <summary>A prospective reactive mutation exceeded the finite captured-instance envelope.</summary>
    public const string InputTooLarge = "rule.input_too_large";

    // ── Publish-time (compile) rejections (throw RuleCompilationException) ──

    /// <summary>A cyclic definition was rejected at publish (carries the cycle path).</summary>
    public const string CompileCycle = "rule.compile.cycle";

    /// <summary>The dependency depth exceeded the static bound at publish.</summary>
    public const string CompileDepthExceeded = "rule.compile.depth_exceeded";

    /// <summary>A single rule referenced more cells than the static bound.</summary>
    public const string CompileTooManyRefs = "rule.compile.too_many_refs";

    /// <summary>A rule's AST exceeded the static node-count bound.</summary>
    public const string CompileAstTooLarge = "rule.compile.ast_too_large";

    /// <summary>A string literal exceeded the static length bound.</summary>
    public const string CompileLiteralTooLong = "rule.compile.literal_too_long";

    /// <summary>A rule expression was not parseable JSON / well-formed JsonLogic.</summary>
    public const string CompileInvalidExpression = "rule.compile.invalid_expression";

    /// <summary>A JsonSchema-tier rule was not a valid draft 2020-12 JSON Schema.</summary>
    public const string CompileInvalidJsonSchema = "rule.compile.invalid_json_schema";

    /// <summary>A rule declared a tier the v1 evaluator does not implement (e.g. PowerFx).</summary>
    public const string CompileUnsupportedTier = "rule.compile.unsupported_tier";

    /// <summary>A rule declares an action outside the closed action vocabulary.</summary>
    public const string CompileUnknownAction = "rule.compile.unknown_action";

    /// <summary>A scope-grammar reference was malformed or invalid for the rule's scope.</summary>
    public const string CompileBadGrammar = "rule.compile.bad_grammar";

    /// <summary>True for a publish-time (compile) rejection code, which a guard returns as its error (T-687).</summary>
    public static bool IsCompileRejection(string? code) => code?.StartsWith("rule.compile.", StringComparison.Ordinal) == true;
}

namespace Harborline.Foundation.RuleEngine;

/// <summary>
/// Fail-closed resource bounds for the rule engine (SPINE-1 design §4 — "the
/// security crux"). Every bound is fail-closed: exceeding a static bound rejects
/// the definition at publish; exceeding a runtime bound aborts evaluation with a
/// stable code and fails closed. The <b>mechanism</b> (fail-closed, static where
/// possible) is fixed (Decision DG); the <b>numbers</b> are CIC-tunable (Decision DF).
/// </summary>
/// <remarks>
/// Both tiers enforce the identical static caps (so the client rejects the same
/// definitions the server does); the runtime step budget + wall-clock ceiling are
/// the server's authoritative backstop (the client's are advisory UX).
/// </remarks>
public sealed record RuleEngineLimits
{
    /// <summary>Max addressable graph nodes (fields × rows + aggregates). Instance-time.</summary>
    public int MaxGraphNodes { get; init; } = 5_000;

    /// <summary>Max child-table rows feeding one aggregate. Instance-time.</summary>
    public int MaxTableRowsPerAggregate { get; init; } = 2_000;

    /// <summary>Max dependency depth (longest path). Publish-time (static).</summary>
    public int MaxDependencyDepth { get; init; } = 64;

    /// <summary>Max references from a single rule. Publish-time (static).</summary>
    public int MaxReferencesPerRule { get; init; } = 64;

    /// <summary>Max AST node count for one rule. Publish-time (static).</summary>
    public int MaxAstNodes { get; init; } = 256;

    /// <summary>Max string-literal length inside an expression. Publish-time (static).</summary>
    public int MaxLiteralLength { get; init; } = 4_096;

    /// <summary>Per-instance total evaluation step budget (ops). Runtime.</summary>
    public int StepBudget { get; init; } = 250_000;

    /// <summary>Per-evaluation wall-clock ceiling. Runtime (.NET authoritative backstop).</summary>
    public TimeSpan WallClockCeiling { get; init; } = TimeSpan.FromMilliseconds(250);

    /// <summary>The CIC-default v1 limits (SPINE-1 §4 table).</summary>
    public static RuleEngineLimits Default { get; } = new();
}

namespace Harborline.Foundation.RuleEngine;

/// <summary>
/// The <b>non-authoritative liveness guard</b> for a single evaluation (SPINE-1 design §4,
/// as amended by the D1 ratification 2026-07-01).
/// </summary>
/// <remarks>
/// <para>
/// The per-evaluation wall-clock ceiling (and any external <see cref="System.Threading.CancellationToken"/>)
/// is time- and hardware-dependent: it can trip on the slower .NET tier but not the faster TS tier — or
/// differently on replay / future hardware. If a wall-clock trip produced an evaluation <i>outcome</i>
/// (a <c>rule.timeout</c> <see cref="Model.Validity"/>/<see cref="Model.ComputedValue"/>), the two tiers
/// would emit divergent <see cref="Model.RuleOutcome"/> values for the same input, breaking
/// replay-determinism and the byte-identical conformance corpus.
/// </para>
/// <para>
/// Therefore the wall-clock is NOT outcome-affecting. The <b>op-budget</b>
/// (<see cref="RuleEngineLimits.StepBudget"/> → <c>rule.budget_exceeded</c>) is the SOLE authoritative,
/// deterministic, outcome-affecting bound. When the wall-clock (or a cancellation token) trips, the engine
/// throws THIS infrastructure exception — identical in kind on both tiers (the TS tier throws
/// <c>RuleTimeout</c>) — instead of returning a divergent evaluation result. Callers treat it as an
/// infrastructure fault (fail the write closed / retry / degrade the render), never as a rule verdict.
/// </para>
/// </remarks>
public sealed class RuleEngineTimeoutException : Exception
{
    /// <summary>The stable diagnostic code for this infrastructure fault (<c>rule.timeout</c>).</summary>
    public string Code => RuleEngineCodes.Timeout;

    /// <summary>Creates the timeout with the default message.</summary>
    public RuleEngineTimeoutException()
        : base("Rule evaluation exceeded the wall-clock liveness ceiling or was cancelled. "
             + "This is a non-authoritative infrastructure fault, not an evaluation outcome.")
    {
    }
}

