/// <summary>T-590 slice 3: named predicates, exact calculation pins, legality citations and the bounded fold.</summary>
public sealed class NamedReferenceTests
{
    private static readonly GuardEvaluator Guard = new(new FixedClock(new DateTimeOffset(2026, 9, 24, 0, 0, 0, TimeSpan.Zero)));

    private static RuleContextSnapshot Facts(string json)
        => RuleContextSnapshot.Capture(JsonNode.Parse(json)!.AsObject().ToDictionary(p => p.Key, p => p.Value?.DeepClone()));

    [Fact(DisplayName = "rules-ck-22, rules-auth-9: one immutable named predicate is authored once and reused by a view filter, a rule condition, an automation condition, a report population and a Layout guard through its exact pin")]
    public void Named_predicate_is_authored_once_and_reused_by_every_consumer_kind()
    {
        var v1 = new NamedPredicate("overdue", "1.0.0", """{">":[{"var":"days_late"},30]}""");
        var v2 = new NamedPredicate("overdue", "2.0.0", """{">":[{"var":"days_late"},60]}""");
        var closure = new PinnedClosure([v1, v2], []);

        foreach (var consumer in Enum.GetValues<PredicateConsumer>())
        {
            var rule = NamedReferences.Bind(consumer, v1.Pin, closure);
            Assert.Equal(v1.Expression, rule.Expression);
            Assert.True(Guard.EvaluateGuard(rule, Facts("""{"days_late":45}"""), RuleEvalScope.Root, TestAdmission.Any).Ok, consumer.ToString());
        }
        // A new version does not move a consumer that pinned the old one.
        Assert.False(Guard.EvaluateGuard(NamedReferences.Bind(PredicateConsumer.ViewFilter, v2.Pin, closure), Facts("""{"days_late":45}"""), RuleEvalScope.Root, TestAdmission.Any).Ok);
        Assert.NotEqual(v1.Pin.Digest, v2.Pin.Digest);

        // Resolution is from the pinned closure only: absent, tampered or floating pins refuse.
        Assert.Equal(NamedReferences.Unresolved, Assert.Throws<NamedReferenceException>(() => NamedReferences.Bind(PredicateConsumer.RuleCondition, v1.Pin, new PinnedClosure([v2], []))).Code);
        Assert.Equal(NamedReferences.DigestMismatch, Assert.Throws<NamedReferenceException>(() => NamedReferences.Bind(PredicateConsumer.RuleCondition, v1.Pin with { Digest = v2.Pin.Digest }, closure)).Code);
        Assert.Equal(NamedReferences.Floating, Assert.Throws<NamedReferenceException>(() => NamedReferences.Bind(PredicateConsumer.RuleCondition, v1.Pin with { Version = "latest" }, closure)).Code);
        Assert.Equal(NamedReferences.Floating, Assert.Throws<NamedReferenceException>(() => new NamedPredicate("overdue", "^1.0", "true")).Code);
        // The element is immutable: no settable member.
        Assert.DoesNotContain(typeof(NamedPredicate).GetProperties(), p => p.SetMethod is { IsPublic: true });
    }

    [Fact(DisplayName = "rules-ck-23, rules-auth-14: Compute is a pure call through an exact named calculation pin that returns a typed value and writes nothing")]
    public void Compute_is_a_pure_call_through_an_exact_pin()
    {
        var calculation = new NamedCalculation("line-total", "1.0.0", """{"money.mul":[{"var":"price"},{"var":"qty"}]}""");
        var closure = new PinnedClosure([], [calculation]);
        var facts = new Dictionary<string, JsonNode?> { ["price"] = "2.50", ["qty"] = 4 };
        var snapshot = RuleContextSnapshot.Capture(facts);

        var first = NamedReferences.Compute(calculation.Pin, closure, Guard, snapshot, TestAdmission.Any);
        var second = NamedReferences.Compute(calculation.Pin, closure, Guard, snapshot, TestAdmission.Any);
        Assert.Equal("10", first.Value!.GetValue<string>());
        Assert.Equal(first.Value!.ToJsonString(), second.Value!.ToJsonString());
        Assert.Equal(2, facts.Count); // the caller's data is untouched

        Assert.Equal(NamedReferences.Floating, Assert.Throws<NamedReferenceException>(() => NamedReferences.Compute(calculation.Pin with { Version = "*" }, closure, Guard, snapshot, TestAdmission.Any)).Code);
        Assert.Equal(NamedReferences.DigestMismatch, Assert.Throws<NamedReferenceException>(() => NamedReferences.Compute(calculation.Pin with { Digest = new string('0', 64) }, closure, Guard, snapshot, TestAdmission.Any)).Code);
        // There is no inline form: the only way in is a pin.
        Assert.All(typeof(NamedReferences).GetMethods(BindingFlags.Public | BindingFlags.Static).Where(m => m.Name == "Compute"),
            method => Assert.DoesNotContain(method.GetParameters(), p => p.ParameterType == typeof(string)));
    }

    [Fact(DisplayName = "rules-ck-24, rules-auth-15: a legality rule set is cited by exact pin with provenance, jurisdiction and dates preserved, and never interpreted")]
    public void Legality_rule_set_is_cited_never_interpreted()
    {
        var digest = new string('a', 64);
        var citation = new LegalityRuleSetCitation("pack.payroll-uk", "minimum-wage", "2026.1.0", digest, "GB", new DateOnly(2026, 4, 1), new DateOnly(2027, 3, 31));
        Assert.Equal("""{"digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","effectiveFrom":"2026-04-01","effectiveTo":"2027-03-31","jurisdiction":"GB","name":"minimum-wage","packageId":"pack.payroll-uk","version":"2026.1.0"}""", citation.CanonicalJson);

        // No body, no expression, no evaluate: Rules cannot interpret what it only cites.
        Assert.DoesNotContain(typeof(LegalityRuleSetCitation).GetMembers(BindingFlags.Public | BindingFlags.Instance),
            m => m.Name.Contains("Expression", StringComparison.Ordinal) || m.Name.Contains("Evaluate", StringComparison.Ordinal) || m.Name.Contains("Body", StringComparison.Ordinal));
        Assert.Throws<NamedReferenceException>(() => new LegalityRuleSetCitation("pack", "minimum-wage", "latest", digest, "GB", new DateOnly(2026, 4, 1), null));
        Assert.Throws<NamedReferenceException>(() => new LegalityRuleSetCitation("pack", "minimum-wage", "1.0.0", digest, " ", new DateOnly(2026, 4, 1), null));
        Assert.Throws<NamedReferenceException>(() => new LegalityRuleSetCitation("pack", "minimum-wage", "1.0.0", digest, "GB", new DateOnly(2026, 4, 1), new DateOnly(2026, 3, 1)));
    }

    [Fact(DisplayName = "rules-eng-16, rules-bound-4: agg folds only a named bounded child collection with a registered fold, and every registered fold executes")]
    public void Agg_is_a_bounded_fold_over_a_named_child_collection()
    {
        var instance = RuleInstance.FromJson(JsonNode.Parse("""{"items":[{"id":"a","amount":2,"ok":true},{"id":"b","amount":5,"ok":false}]}""")!.AsObject());
        foreach (var fold in BuiltInFunctionRegister.AggregateFolds)
        {
            var column = fold is "any" or "all" ? "ok" : "amount";
            var compiled = RuleCompiler.Compile([RuleDefinitionFactory.Create("f", RuleTier.JsonLogic, RuleScope.Field, "out", $$"""{"var":"table.{{fold}}(items.{{column}})"}""", RuleActionKind.Compute)]);
            var value = new FormRuleGraph(compiled, new FixedClock(DateTimeOffset.UnixEpoch), TestAdmission.Any).EvaluateInstance(instance).Values["field:out"];
            Assert.Equal(Model.ValueState.Resolved, value.State);
        }
        // An unregistered fold, a dynamic collection or a non-literal fold is not a bounded fold.
        foreach (var expression in new[] { """{"agg":["median","items","amount"]}""", """{"agg":["search","items","amount"]}""", """{"agg":["sum",{"var":"field.section"},"amount"]}""", """{"var":"table.lookup(items.amount)"}""" })
            Assert.Equal(RuleEngineCodes.CompileBadGrammar, Assert.Throws<RuleCompilationException>(() => RuleCompiler.Compile(
                [RuleDefinitionFactory.Create("f", RuleTier.JsonLogic, RuleScope.Field, "out", expression, RuleActionKind.Compute)])).Code);
    }

    [Fact(DisplayName = "rules-auth-27, rules-auth-28: search, query, interval overlap, taxonomy traversal, catalogue-measure calculation and unbounded folds refuse at publish")]
    public void Search_query_taxonomy_and_measure_calculation_refuse()
    {
        string[] refused =
        [
            """{"search":["assets","pump"]}""", """{"query":["assets",{"==":[{"var":"kind"},"pump"]}]}""",
            """{"interval.overlaps":[{"var":"a"},{"var":"b"}]}""", """{"taxonomy.subsumes":["asset-class","rotating","pump"]}""",
            """{"taxonomy.succeeds":["status","open","closed"]}""", """{"coding.descendant":[{"var":"c"},"sys","parent"]}""",
            """{"measure":["asset.condition-score"]}""", """{"reduce":[{"var":"items"},{"+":[1,1]},0]}""",
            """{"filter":[{"var":"items"},true]}""", """{"map":[{"var":"items"},1]}""",
        ];
        foreach (var expression in refused)
            Assert.Equal(RuleEngineCodes.CompileInvalidExpression, Assert.Throws<RuleCompilationException>(() => RuleCompiler.Compile(
                [RuleDefinitionFactory.Create("r", RuleTier.JsonLogic, RuleScope.Field, "out", expression, RuleActionKind.Compute)])).Code);

        // coding.is is exact membership: it never matches a descendant, so no subsumption hides in it.
        var coded = RuleDefinitionFactory.Create("c", RuleTier.JsonLogic, RuleScope.Schema, "", """{"coding.is":[{"var":"c"},"asset-class","rotating"]}""", RuleActionKind.Validate);
        Assert.True(Guard.EvaluateGuard(coded, Facts("""{"c":{"system":"asset-class","code":"rotating"}}"""), RuleEvalScope.Root, TestAdmission.Any).Ok);
        Assert.False(Guard.EvaluateGuard(coded, Facts("""{"c":{"system":"asset-class","code":"pump"}}"""), RuleEvalScope.Root, TestAdmission.Any).Ok);

        // The engine assembly cannot reach a catalogue or a search: it references only contracts and schema validation.
        Assert.Equal(["Harborline.Contracts", "Harborline.Kernel.SchemaValidation", "System.Runtime"], typeof(GuardEvaluator).Assembly.GetReferencedAssemblies()
            .Select(a => a.Name!).Where(n => n.StartsWith("Harborline", StringComparison.Ordinal) || n == "System.Runtime").Order(StringComparer.Ordinal));
    }

    [Fact(DisplayName = "rules-eng-16: the asset-scoring decision table (ADR 0096 ruling 5c) folds supplied measure results already in scope and never calls the catalogue")]
    public void Asset_scoring_decision_table_reads_supplied_measure_values()
    {
        var table = new DecisionTableSkin("asset.score", RuleScope.Field, "score", RuleActionKind.Compute, HitPolicy.Priority,
            ["field.measure_condition_score", "field.measure_criticality"],
            [
                new DecisionRow([DecisionCell.Range(JsonValue.Create(0), JsonValue.Create(40)), DecisionCell.Compare(">=", JsonValue.Create(3))], JsonValue.Create("replace"), 10),
                new DecisionRow([DecisionCell.Range(JsonValue.Create(0), JsonValue.Create(70)), DecisionCell.Wildcard], JsonValue.Create("inspect"), 5),
            ],
            NoMatch.WithDefault(JsonValue.Create("monitor")));
        var rule = DecisionTableCompiler.Compile(table);
        var graph = new FormRuleGraph(RuleCompiler.Compile([rule]), new FixedClock(DateTimeOffset.UnixEpoch), TestAdmission.Any);
        string Score(string json) => graph.EvaluateInstance(RuleInstance.FromJson(JsonNode.Parse(json)!.AsObject())).Values["field:score"].Value!.GetValue<string>();

        Assert.Equal("replace", Score("""{"measure_condition_score":35,"measure_criticality":4}"""));
        Assert.Equal("inspect", Score("""{"measure_condition_score":35,"measure_criticality":1}"""));
        Assert.Equal("monitor", Score("""{"measure_condition_score":90,"measure_criticality":5}"""));
    }
}

using Xunit;

namespace Harborline.Foundation.RuleEngine.Tests;

/// <summary>
/// D1 ratification fix 3 (2026-07-01): the <b>operator-catalog erosion guard</b>. A STANDING
/// arch-test that pins the CLOSED <c>harborline-jsonlogic/v1</c> operator set + the regex-exclusion
/// invariant, so a new operator (or a regex/pattern construct) cannot slip into the evaluator at a
/// version bump without tripping this test — the "one convenience operator erodes A into B, one PR
/// at a time" (Form.io) trajectory the D1 council named. Adding/removing/renaming an operator
/// REQUIRES a deliberate edit to <see cref="FrozenV1Operators"/> below — which is exactly the review
/// checkpoint the guard exists to force. It source-scans the evaluator so it is author-independent
/// (it cannot be defeated by forgetting to update a parallel catalog constant).
/// </summary>
public sealed class OperatorCatalogArchTests
{
    /// <summary>
    /// The frozen, closed <c>harborline-jsonlogic/v1</c> operator set (design §1.4 / README). DELIBERATELY
    /// EXCLUDED: any regex/pattern operator (ReDoS structurally absent — Decision DG); and
    /// <c>map</c>/<c>filter</c>/<c>reduce</c>/<c>merge</c> (deferred — child-table folds use <c>agg</c>).
    /// The TS tier pins the IDENTICAL set in <c>operator-catalog.test.ts</c>.
    /// </summary>
    private static readonly IReadOnlySet<string> FrozenV1Operators = new HashSet<string>(StringComparer.Ordinal)
    {
        "var", "missing", "missing_some",
        "==", "!=", "===", "!==", "!", "!!", "and", "or", "if",
        ">", ">=", "<", "<=",
        "+", "-", "*", "/", "%", "min", "max",
        "in", "cat",
        "agg", "money.add", "money.sub", "money.mul",
        "date.add", "date.diff", "date.today", "coding.is",
    };

    [Fact]
    public void Evaluator_implements_EXACTLY_the_frozen_v1_operator_set()
    {
        // Since T-590 the R1 register is the evaluator's only dispatch table (rules-eng-27), so the
        // guard pins the register instead of scanning a switch that no longer exists.
        var implemented = Functions.BuiltInFunctionRegister.Functions.Select(f => f.Key).ToHashSet(StringComparer.Ordinal);

        var added = implemented.Except(FrozenV1Operators).OrderBy(s => s, StringComparer.Ordinal).ToList();
        var removed = FrozenV1Operators.Except(implemented).OrderBy(s => s, StringComparer.Ordinal).ToList();

        Assert.True(added.Count == 0,
            $"NEW operator(s) added to the register without deliberate review: [{string.Join(", ", added)}]. "
            + "The harborline-jsonlogic/v1 set is CLOSED (D1). If intended, amend FrozenV1Operators + the TS "
            + "operator-catalog test + the README operator table + design §1.4 — never silently.");
        Assert.True(removed.Count == 0,
            $"operator(s) removed from the register: [{string.Join(", ", removed)}]. Removing an operator "
            + "breaks the closed v1 set — amend FrozenV1Operators deliberately if this is intended.");
    }

    [Fact]
    public void Evaluator_uses_NO_regex_construct_so_ReDoS_is_structurally_absent()
    {
        string source = ReadEvaluatorSource();
        foreach (var banned in new[] { "Regex", "RegularExpressions", "GeneratedRegex" })
        {
            Assert.False(source.Contains(banned, StringComparison.Ordinal),
                $"the Tier-2 evaluator must not use '{banned}': regex/pattern is excluded from v1 (Decision DG) "
                + "so the ReDoS class is structurally absent. Pattern validation stays in Tier-1 JSON-Schema.");
        }
    }

    [Fact]
    public void No_frozen_operator_names_a_regex_or_pattern_construct()
    {
        foreach (var op in FrozenV1Operators)
        {
            foreach (var banned in new[] { "regex", "pattern", "match", "search" })
            {
                Assert.False(op.Contains(banned, StringComparison.OrdinalIgnoreCase),
                    $"operator '{op}' names a regex/pattern construct — excluded from v1 (Decision DG).");
            }
        }
    }

    private static string ReadEvaluatorSource()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "repository.yaml"))) dir = dir.Parent;
        Assert.True(dir is not null, "could not locate the Harborline Platform repository root to read the evaluator source");
        string path = Path.Combine(dir!.FullName, "projections", "dotnet", "foundation", "hlp.foundation.rule-runtime", "Evaluation", "HarborlineJsonLogic.cs");
        Assert.True(File.Exists(path), $"evaluator source not found at {path}");
        return File.ReadAllText(path);
    }
}

using System.Text.Json.Nodes;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text;

using Harborline.Foundation.RuleEngine.Compilation;
using Harborline.Foundation.RuleEngine.Context;
using Harborline.Foundation.RuleEngine.Graph;
using Harborline.Foundation.RuleEngine.Model;
using Harborline.Foundation.RuleEngine.Skins;


using Xunit;

namespace Harborline.Foundation.RuleEngine.Tests;

/// <summary>
/// .NET integrity-tier unit coverage (SPINE-1 §6.2): graph build + cycle rejection,
/// every resource bound (fail-closed with the exact stable code), the guard evaluator,
/// visibility merge, reactive re-eval (raw-field dependents + referential stability),
/// incremental child-table edits, and the fail-closed save gate.
/// </summary>
public sealed class RuleEngineUnitTests
{
    private static readonly DateTimeOffset Clock = new(2026, 6, 30, 0, 0, 0, TimeSpan.Zero);

    private static RuleDefinition Compute(string id, string target, string expr, RuleScope scope = RuleScope.Field) => RuleDefinitionFactory.Create(id, RuleTier.JsonLogic, scope, target, expr, RuleActionKind.Compute);

    private static RuleInstance Instance(string json)
        => RuleInstance.FromJson(JsonNode.Parse(json)!.AsObject());

    private static FormRuleGraph Graph(IReadOnlyList<RuleDefinition> rules, RuleEngineLimits? limits = null)
        => new(RuleCompiler.Compile(rules, limits), new FixedClock(Clock), TestAdmission.Any, limits);

    [Fact]
    public void Lowered_asts_show_the_grammar_rewrite_and_are_copies_the_caller_cannot_use_to_alter_the_graph()
    {
        var compiled = RuleCompiler.Compile([Compute("line.total", "lines/amount", "{\"var\":\"parent.z\"}", RuleScope.Row)]);

        var lowered = Assert.Single(compiled.LoweredAsts);
        Assert.True(JsonNode.DeepEquals(JsonNode.Parse("{\"var\":\"field.z\"}"), lowered));

        lowered!.AsObject()["var"] = "field.tampered";
        Assert.True(JsonNode.DeepEquals(JsonNode.Parse("{\"var\":\"field.z\"}"), compiled.LoweredAsts[0]));
    }

    [Fact]
    public void Graph_and_guard_reject_a_missing_business_clock()
    {
        var compiled = RuleCompiler.Compile([]);

        Assert.Throws<ArgumentNullException>(() => new FormRuleGraph(compiled, clock: null!, TestAdmission.Any));
        Assert.Throws<ArgumentNullException>(() => new GuardEvaluator(clock: null!));
    }

    // ── cycle + tier rejection ────────────────────────────────────────────────

    [Fact]
    public void Compile_rejects_cycle_with_path_diagnostic()
    {
        var rules = new[]
        {
            Compute("c.x", "x", "{\"+\":[{\"var\":\"y\"},1]}"),
            Compute("c.y", "y", "{\"+\":[{\"var\":\"x\"},1]}"),
        };
        var ex = Assert.Throws<RuleCompilationException>(() => RuleCompiler.Compile(rules));
        Assert.Equal(RuleEngineCodes.CompileCycle, ex.Code);
        Assert.NotNull(ex.CyclePath);
        Assert.NotEmpty(ex.CyclePath!);
    }

    [Fact]
    public void Compile_rejects_powerfx_tier()
    {
        var rule = RuleDefinitionFactory.Create("c.p", RuleTier.PowerFx, RuleScope.Field, "p", "{\"var\":\"a\"}", RuleActionKind.Compute);
        var ex = Assert.Throws<RuleCompilationException>(() => RuleCompiler.Compile(new[] { rule }));
        Assert.Equal(RuleEngineCodes.CompileUnsupportedTier, ex.Code);
    }

    [Fact]
    public void Compile_refuses_malformed_json_schema_tier_rule_with_owning_id()
    {
        var rule = RuleDefinitionFactory.Create("schema.malformed", RuleTier.JsonSchema,
            RuleScope.Schema, "", "{\"type\":", RuleActionKind.Validate);

        var error = Assert.Throws<RuleCompilationException>(() => RuleCompiler.Compile(new[] { rule }));

        Assert.Equal(RuleEngineCodes.CompileInvalidJsonSchema, error.Code);
        Assert.Equal("schema.malformed", error.RuleId);
        Assert.StartsWith("rule 'schema.malformed':", error.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void Compile_admits_valid_json_schema_tier_rule()
    {
        var rule = RuleDefinitionFactory.Create("schema.valid", RuleTier.JsonSchema, RuleScope.Schema, "",
            """{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"name":{"type":"string"}}}""",
            RuleActionKind.Validate);

        var compiled = RuleCompiler.Compile(new[] { rule });

        Assert.Equal(0, compiled.RuleCount);
    }

    [Theory]
    [InlineData(-1)]
    [InlineData(99)]
    public void CompilerDoesNotInterpretAnUnknownTierAsJsonLogic(int tier)
    {
        var rule = RuleDefinitionFactory.Create("unknown-tier", (RuleTier)tier,
            RuleScope.Field, "total", "1", RuleActionKind.Compute);

        var error = Assert.Throws<RuleCompilationException>(() => RuleCompiler.Compile(new[] { rule }));

        Assert.Equal(RuleEngineCodes.CompileUnsupportedTier, error.Code);
        Assert.Equal("unknown-tier", error.RuleId);
    }

    [Theory]
    [InlineData(-1)]
    [InlineData(99)]
    public void CompilerDoesNotInterpretAnUnknownActionAsVisibility(int action)
    {
        var rule = RuleDefinitionFactory.Create("unknown-action", RuleTier.JsonLogic,
            RuleScope.Field, "total", "true", (RuleActionKind)action);

        var error = Assert.Throws<RuleCompilationException>(() => RuleCompiler.Compile(new[] { rule }));

        Assert.Equal("rule.compile.unknown_action", error.Code);
        Assert.Equal("unknown-action", error.RuleId);
    }

    [Theory]
    [InlineData("{\"unknown_operator\":[]}")]
    [InlineData("{\"regex\":[\"a\",\".*\"]}")]
    [InlineData("{\"if\":[false,{\"unknown_operator\":[]},true]}")]
    public void CompilerRefusesUnsupportedOperatorsWithoutNeedingAnyRecords(string expression)
    {
        var rule = Compute("closed-grammar", "total", expression);

        var error = Assert.Throws<RuleCompilationException>(() => RuleCompiler.Compile(new[] { rule }));

        Assert.Equal(RuleEngineCodes.CompileInvalidExpression, error.Code);
        Assert.Equal("closed-grammar", error.RuleId);
    }

    [Theory]
    [InlineData("[{\"unknown_operator\":[]}]")]
    [InlineData("{\"metadata\":{\"unknown_operator\":[]},\"label\":\"literal\"}")]
    public void OperatorAdmissionDoesNotInterpretLiteralDataAsExecutableSyntax(string expression)
    {
        Assert.Equal(1, RuleCompiler.Compile(new[] { Compute("literal-data", "result", expression) }).RuleCount);
    }

    [Theory]
    [InlineData("{\"date.today\":[\"unexpected\"]}")]
    [InlineData("{\"coding.is\":[{\"var\":\"code\"},\"system\"]}")]
    public void CompilerRefusesExecutableOperatorsWithInvalidArityBeforeEvaluation(string expression)
    {
        var error = Assert.Throws<RuleCompilationException>(() =>
            RuleCompiler.Compile(new[] { Compute("invalid-arity", "result", expression) }));

        Assert.Equal(RuleEngineCodes.CompileInvalidExpression, error.Code);
        Assert.Equal("invalid-arity", error.RuleId);
    }

    // ── static bounds ─────────────────────────────────────────────────────────

    [Theory]
    [InlineData(64, true)]
    [InlineData(65, false)]
    public void DefaultCompilerReferenceBoundaryIsInclusive(int count, bool admitted)
    {
        var refs = string.Join(",", Enumerable.Range(0, count).Select(i => $"{{\"var\":\"r{i}\"}}"));
        var rules = new[] { Compute("reference-boundary", "total", $"{{\"+\":[{refs}]}}") };

        if (admitted)
            Assert.Equal(1, RuleCompiler.Compile(rules).RuleCount);
        else
            Assert.Equal(RuleEngineCodes.CompileTooManyRefs,
                Assert.Throws<RuleCompilationException>(() => RuleCompiler.Compile(rules)).Code);
    }

    [Theory]
    [InlineData(64, true)]
    [InlineData(65, false)]
    public void DefaultCompilerDependencyDepthBoundaryIsInclusive(int depth, bool admitted)
    {
        var rules = Enumerable.Range(0, depth)
            .Select(i => Compute($"dependency-{i}", $"f{i}", $"{{\"var\":\"f{i + 1}\"}}"))
            .ToArray();

        if (admitted)
            Assert.Equal(depth, RuleCompiler.Compile(rules).RuleCount);
        else
            Assert.Equal(RuleEngineCodes.CompileDepthExceeded,
                Assert.Throws<RuleCompilationException>(() => RuleCompiler.Compile(rules)).Code);
    }

    [Fact]
    public void Compiler_enforces_ast_and_literal_boundaries_at_and_immediately_over_the_configured_limit()
    {
        var astLimits = RuleEngineLimits.Default with { MaxAstNodes = 1 };
        Assert.Equal(1, RuleCompiler.Compile(new[] { Compute("ast-at", "x", "1") }, astLimits).RuleCount);
        Assert.Equal(RuleEngineCodes.CompileAstTooLarge,
            Assert.Throws<RuleCompilationException>(() => RuleCompiler.Compile(new[] { Compute("ast-over", "x", "{\"!\":[true]}") }, astLimits)).Code);

        var literalLimits = RuleEngineLimits.Default with { MaxLiteralLength = 1 };
        Assert.Equal(1, RuleCompiler.Compile(new[] { Compute("literal-at", "x", "\"a\"") }, literalLimits).RuleCount);
        Assert.Equal(RuleEngineCodes.CompileLiteralTooLong,
            Assert.Throws<RuleCompilationException>(() => RuleCompiler.Compile(new[] { Compute("literal-over", "x", "\"ab\"") }, literalLimits)).Code);
    }

    [Fact]
    public void Compiler_derives_empty_literal_and_short_dependency_programs_without_host_depth_iteration()
    {
        var large = RuleEngineLimits.Default with { MaxDependencyDepth = int.MaxValue };
        Assert.True(RuleCompiler.Compile([], large).WorkProof.MaximumEvaluationWork >= 0);
        Assert.True(RuleCompiler.Compile(new[] { Compute("literal", "x", "1") }, large).WorkProof.MaximumResultBytes >= 1);
        Assert.Equal(2, RuleCompiler.Compile(new[] { Compute("a", "a", "{\"var\":\"b\"}"), Compute("b", "b", "1") }, large).RuleCount);
    }

    [Fact]
    public void Graph_instantiates_proof_for_independently_configured_structural_dimensions()
    {
        var compiled = RuleCompiler.Compile(new[] { Compute("row-aware", "x", "{\"var\":\"table.sum(items.amount)\"}") },
            RuleEngineLimits.Default with { MaxTableRowsPerAggregate = 1, MaxGraphNodes = 2 });
        var graph = new FormRuleGraph(compiled, new FixedClock(Clock), TestAdmission.Any,
            RuleEngineLimits.Default with { MaxTableRowsPerAggregate = 2, MaxGraphNodes = 3 });
