/// <summary>
/// The ADR 0146 D5 named-rule registry + version policies (Wave 1 unification floor). Pins:
/// resolve <c>latest</c>/<c>pinned</c>/<c>draft</c>; the board-F6 draft-exclusion MECHANISM
/// (production never returns a draft; sandbox reaches it); the S-8 monotonic-watermark offline
/// determinism (order-independent "latest"); D7 instance-pin deterministic replay; and the
/// HomeEpochFence read-tip-reject-stale discipline on the per-node compile/cache swap.
/// </summary>
public sealed class RuleRegistryTests
{
    private const string Tenant = "t1";
    private const string Key = "invoice.approval-threshold";

    private static RuleDefinition Def(string id) => RuleDefinitionFactory.Create(id, RuleTier.JsonLogic, RuleScope.Field, "f", "{\"+\":[1,2]}", RuleActionKind.Compute);

    private static PublishedRuleVersion Pub(string version, bool draft = false)
        => new(Key, version, draft, Def($"{Key}@{version}"));

    // ── version comparator (S-8 watermark) ────────────────────────────────────

    [Fact]
    public void RuleVersion_orders_numeric_segments_not_lexically()
    {
        Assert.True(RuleVersion.Compare("1.10.0", "1.2.0") > 0);   // 10 > 2 numerically, not "10" < "2"
        Assert.True(RuleVersion.Compare("2.0.0", "1.9.9") > 0);
        Assert.Equal(0, RuleVersion.Compare("1.0.0", "1.0.0"));
        Assert.True(RuleVersion.Compare("1.0.0-rc1", "1.0.0") < 0); // pre-release precedes stable
        Assert.True(RuleVersion.IsDowngrade("1.2.0", "1.1.0"));      // candidate below watermark
        Assert.False(RuleVersion.IsDowngrade("1.2.0", "1.3.0"));
    }

    [Fact]
    public void RuleVersion_refuses_a_malformed_segment()
    {
        var error = Assert.Throws<FormatException>(() => RuleVersion.Compare("99.bad.0", "1.0.0"));
        Assert.Contains("99.bad.0", error.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void Publish_refuses_an_equal_version_with_a_different_body()
    {
        var registry = new RuleRegistry();
        var first = Pub("1.0.0");
        registry.Publish(Tenant, first);
        registry.Publish(Tenant, first);

        var conflict = Assert.Throws<RuleVersionConflictException>(() =>
            registry.Publish(Tenant, new PublishedRuleVersion(
                Key,
                "1.0.0",
                false,
                Def($"{Key}@different"))));

        Assert.Equal("1.0.0", conflict.Version);
        Assert.Equal(first.Definition, registry.Resolve(
            Tenant, Key, RuleVersionPolicy.Latest, RuleResolveScope.Production).Definition);
    }

    // ── latest ────────────────────────────────────────────────────────────────

    [Fact]
    public void Resolve_latest_picks_the_highest_published_version()
    {
        var reg = new RuleRegistry();
        reg.Publish(Tenant, Pub("1.0.0"));
        reg.Publish(Tenant, Pub("1.10.0"));
        reg.Publish(Tenant, Pub("1.2.0"));

        var r = reg.Resolve(Tenant, Key, RuleVersionPolicy.Latest, RuleResolveScope.Production);

        Assert.True(r.IsResolved);
        Assert.Equal("1.10.0", r.Version);
        Assert.NotNull(r.Definition);
    }

    [Fact]
    public void Resolve_latest_is_order_independent_across_offline_peers()
    {
        // Two peers receive the same published set in OPPOSITE sync orders — both converge on the
        // same "latest" (S-8 monotonic determinism; board's "monotonically convergent" property).
        var peerA = new RuleRegistry();
        peerA.Publish(Tenant, Pub("1.0.0"));
        peerA.Publish(Tenant, Pub("2.0.0"));

        var peerB = new RuleRegistry();
        peerB.Publish(Tenant, Pub("2.0.0"));
        peerB.Publish(Tenant, Pub("1.0.0"));

        var a = peerA.Resolve(Tenant, Key, RuleVersionPolicy.Latest, RuleResolveScope.Production);
        var b = peerB.Resolve(Tenant, Key, RuleVersionPolicy.Latest, RuleResolveScope.Production);

        Assert.Equal("2.0.0", a.Version);
        Assert.Equal(a.Version, b.Version);
    }

    // ── draft exclusion (board F6 — a mechanism, not prose) ─────────────────────

    [Fact]
    public void Resolve_latest_excludes_drafts_on_production_but_reaches_them_in_sandbox()
    {
        var reg = new RuleRegistry();
        reg.Publish(Tenant, Pub("1.0.0"));
        reg.Publish(Tenant, Pub("2.0.0", draft: true)); // a higher-versioned DRAFT

        var prod = reg.Resolve(Tenant, Key, RuleVersionPolicy.Latest, RuleResolveScope.Production);
        var sandbox = reg.Resolve(Tenant, Key, RuleVersionPolicy.Latest, RuleResolveScope.Sandbox);

        Assert.Equal("1.0.0", prod.Version);   // production NEVER returns the draft
        Assert.Equal("2.0.0", sandbox.Version); // sandbox sees the draft
    }

    [Fact]
    public void Resolve_draft_policy_is_refused_on_production_and_resolves_in_sandbox()
    {
        var reg = new RuleRegistry();
        reg.Publish(Tenant, Pub("1.0.0"));
        reg.Publish(Tenant, Pub("2.0.0", draft: true));

        var prod = reg.Resolve(Tenant, Key, RuleVersionPolicy.Draft, RuleResolveScope.Production);
        var sandbox = reg.Resolve(Tenant, Key, RuleVersionPolicy.Draft, RuleResolveScope.Sandbox);

        Assert.Equal(RuleResolutionStatus.DraftRefused, prod.Status);
        Assert.False(prod.IsResolved);
        Assert.True(sandbox.IsResolved);
        Assert.Equal("2.0.0", sandbox.Version);
    }

    [Fact]
    public void Resolve_pinned_draft_is_refused_on_production_and_reachable_in_sandbox()
    {
        var reg = new RuleRegistry();
        reg.Publish(Tenant, Pub("3.0.0", draft: true));

        var prod = reg.Resolve(Tenant, Key, RuleVersionPolicy.Pinned("3.0.0"), RuleResolveScope.Production);
        var sandbox = reg.Resolve(Tenant, Key, RuleVersionPolicy.Pinned("3.0.0"), RuleResolveScope.Sandbox);

        Assert.Equal(RuleResolutionStatus.DraftRefused, prod.Status);
        Assert.Equal("3.0.0", prod.Version); // the refused draft version is reported
        Assert.True(sandbox.IsResolved);
        Assert.Equal("3.0.0", sandbox.Version);
    }

    // ── pinned + not-found ──────────────────────────────────────────────────────

    [Fact]
    public void Resolve_pinned_returns_the_exact_version()
    {
        var reg = new RuleRegistry();
        reg.Publish(Tenant, Pub("1.0.0"));
        reg.Publish(Tenant, Pub("2.0.0"));

        var r = reg.Resolve(Tenant, Key, RuleVersionPolicy.Pinned("1.0.0"), RuleResolveScope.Production);

        Assert.True(r.IsResolved);
        Assert.Equal("1.0.0", r.Version); // NOT the latest 2.0.0
    }

    [Fact]
    public void Resolve_returns_not_found_for_unknown_key_or_pin()
    {
        var reg = new RuleRegistry();
        reg.Publish(Tenant, Pub("1.0.0"));

        Assert.Equal(RuleResolutionStatus.NotFound,
            reg.Resolve(Tenant, "no.such.rule", RuleVersionPolicy.Latest, RuleResolveScope.Production).Status);
        Assert.Equal(RuleResolutionStatus.NotFound,
            reg.Resolve(Tenant, Key, RuleVersionPolicy.Pinned("9.9.9"), RuleResolveScope.Production).Status);
        Assert.Equal(RuleResolutionStatus.NotFound,
            reg.Resolve("other-tenant", Key, RuleVersionPolicy.Latest, RuleResolveScope.Production).Status);
    }

    // ── D7 instance pin ─────────────────────────────────────────────────────────

    [Fact]
    public void Pin_freezes_the_version_and_replays_deterministically_past_a_later_publish()
    {
        var reg = new RuleRegistry();
        reg.Publish(Tenant, Pub("1.0.0"));

        var pin = reg.Pin(Tenant, Key, RuleVersionPolicy.Latest, RuleResolveScope.Production);
        Assert.NotNull(pin);
        Assert.Equal("1.0.0", pin!.Version);

        // A newer version publishes AFTER the consumer instance pinned.
        reg.Publish(Tenant, Pub("2.0.0"));

        // Latest now moves; the pin does NOT (deterministic replay against the creation-time version).
        Assert.Equal("2.0.0", reg.Resolve(Tenant, Key, RuleVersionPolicy.Latest, RuleResolveScope.Production).Version);
        Assert.Equal("1.0.0", reg.ResolvePinned(pin, RuleResolveScope.Production).Version);
    }

    [Fact]
    public void Pin_returns_null_when_nothing_resolves()
    {
        var reg = new RuleRegistry();
        Assert.Null(reg.Pin(Tenant, Key, RuleVersionPolicy.Latest, RuleResolveScope.Production));
    }

    // ── compile/cache swap fence (HomeEpochFence discipline) ─────────────────────

    [Fact]
    public void Compile_cache_swap_is_monotonic_and_refuses_a_stale_publish()
    {
        var cache = new RuleCompileCache();
        var g10 = RuleCompiler.Compile(new[] { Def("r@1.0.0") });
        var g11 = RuleCompiler.Compile(new[] { Def("r@1.1.0") });
        var g10Late = RuleCompiler.Compile(new[] { Def("r@1.0.0-late") });

        cache.Swap(Tenant, Key, "1.0.0", g10);
        cache.Swap(Tenant, Key, "1.1.0", g11); // newer installs

        // A stale publish (a lower version arriving late) is REFUSED — the newer AST stands.
        var ex = Assert.Throws<StaleRulePublishException>(() => cache.Swap(Tenant, Key, "1.0.0", g10Late));
        Assert.Equal("1.0.0", ex.StaleVersion);
        Assert.Equal("1.1.0", ex.CurrentVersion);

        Assert.True(cache.TryGet(Tenant, Key, out var cachedVersion, out var cachedGraph));
        Assert.Equal("1.1.0", cachedVersion);        // the newer AST was not overwritten
        Assert.Same(g11, cachedGraph);
    }

    [Fact]
    public void Compile_cache_swap_is_idempotent_for_an_equal_version()
    {
        var cache = new RuleCompileCache();
        var first = RuleCompiler.Compile(new[] { Def("r@2.0.0") });
        var recompiled = RuleCompiler.Compile(new[] { Def("r@2.0.0") });

        cache.Swap(Tenant, Key, "2.0.0", first);
        cache.Swap(Tenant, Key, "2.0.0", recompiled); // equal version re-installs (no throw)

        Assert.True(cache.TryGet(Tenant, Key, out var version, out var graph));
        Assert.Equal("2.0.0", version);
        Assert.Same(recompiled, graph);
    }
}

using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Compilation;
using Harborline.Foundation.RuleEngine.Context;
using Harborline.Foundation.RuleEngine.Explain;
using Harborline.Foundation.RuleEngine.Graph;
using Harborline.Foundation.RuleEngine.Model;


using Xunit;

namespace Harborline.Foundation.RuleEngine.Tests;

/// <summary>
/// ADR 0146 D10 — interactive explainability traces (board F2). Asserts: a trace is emitted on the
/// interactive path and absent unless requested (batch = traceless); the authority filter darkens field
/// references (redact / shredded-subject hash); and — the load-bearing invariant — a field VALUE is NEVER
/// present in any trace param (the trace builder cannot access a resolved value).
/// </summary>
public sealed class RuleTraceTests
{
    // A Visibility rule that HIDES the comp section for high earners: visible iff salary <= 100000.
    private static RuleDefinition HideHighEarnerComp()  => RuleDefinitionFactory.Create(
        Id: "vis.comp",
        Tier: RuleTier.JsonLogic,
        Scope: RuleScope.Section,
        ScopeTarget: "comp",
        Expression: """{ "<=": [ { "var": "salary" }, 100000 ] }""",
        Action: RuleActionKind.Visibility);

    private static (CompiledGraph, RuleEvaluationResult) Evaluate(RuleDefinition rule, JsonObject instance)
    {
        var compiled = RuleCompiler.Compile(new[] { rule });
        var graph = new FormRuleGraph(compiled, TimeProvider.System, TestAdmission.Any, RuleEngineLimits.Default);
        var result = graph.EvaluateInstance(RuleInstance.FromJson(instance));
        return (compiled, result);
    }

    [Fact]
    public void InteractivePath_EmitsTrace_BatchPathTraceless()
    {
        var (compiled, result) = Evaluate(HideHighEarnerComp(), new JsonObject { ["salary"] = 150000 });

        // Batch path: the evaluation itself carries no trace — the result is the same object either way.
        // Interactive path: the caller opts in by building the trace (a pure projection over the result).
        var trace = RuleTraceBuilder.BuildForm(compiled, result);
        Assert.NotEmpty(trace);
        Assert.Single(trace);
        Assert.Equal("vis.comp", trace[0].RuleId);
    }

    [Fact]
    public void HighEarner_IsHidden_TraceCarriesCodeAndFieldRef_NeverTheValue()
    {
        var (compiled, result) = Evaluate(HideHighEarnerComp(), new JsonObject { ["salary"] = 150000 });
        var entry = RuleTraceBuilder.BuildForm(compiled, result).Single();

        Assert.Equal(RuleTraceCodes.Hidden, entry.Code);        // "hidden because of the salary threshold"…
        Assert.Equal("salary", entry.Params["reads"]);          // …with the field REFERENCE…
        Assert.Equal("section:comp", entry.Target);

        // …and NEVER the value (board F2). The salary 150000 (and the threshold literal 100000) appear in
        // no trace param — the builder has no access to a resolved value.
        foreach (var (_, v) in entry.Params)
        {
            Assert.DoesNotContain("150000", v);
            Assert.DoesNotContain("100000", v);
        }
    }

    [Fact]
    public void AuthorityFilter_RedactsUnreadableFieldReference()
    {
        var (compiled, result) = Evaluate(HideHighEarnerComp(), new JsonObject { ["salary"] = 150000 });
        var entry = RuleTraceBuilder.BuildForm(compiled, result, new DenyFilter("salary")).Single();

        Assert.Equal(RuleTraceCodes.Hidden, entry.Code);
        Assert.Equal("[redacted]", entry.Params["reads"]); // the field ref itself is withheld from an unauthorized viewer
    }

    [Fact]
    public void AuthorityFilter_ShreddedSubject_DarkensReferenceToHash()
    {
        var (compiled, result) = Evaluate(HideHighEarnerComp(), new JsonObject { ["salary"] = 150000 });
        var entry = RuleTraceBuilder.BuildForm(compiled, result, new ShredFilter("salary")).Single();

        Assert.StartsWith("#", entry.Params["reads"]);            // reference+hash form (board F2)
        Assert.Equal("#" + Fnv1aRef("salary"), entry.Params["reads"]);
        // Cross-tier anchor: the SAME literal is pinned in the TS tier's trace test — byte-identical hashing.
        Assert.Equal("#8561b279", entry.Params["reads"]);
        Assert.DoesNotContain("salary", entry.Params["reads"]);   // the bare name no longer appears
    }

    [Fact]
    public void ValidationFailure_TraceCarriesCauseCode()
    {
        var rule = RuleDefinitionFactory.Create("v.qty", RuleTier.JsonLogic, RuleScope.Field, "qty",
            """{ ">": [ { "var": "qty" }, 0 ] }""", RuleActionKind.Validate);
        var (compiled, result) = Evaluate(rule, new JsonObject { ["qty"] = -3 });
        var entry = RuleTraceBuilder.BuildForm(compiled, result).Single();

        Assert.Equal(RuleTraceCodes.ValidationFailed, entry.Code);
        Assert.Equal("v.qty", entry.Params["cause"]);          // the rule's own localizable code
        Assert.Equal("qty", entry.Params["reads"]);
        Assert.DoesNotContain("-3", string.Join("|", entry.Params.Values)); // never the value
    }

    [Fact]
    public void ComputeValue_TraceCarriesComputedCode_NotTheComputedValue()
    {
        var rule = RuleDefinitionFactory.Create("c.total", RuleTier.JsonLogic, RuleScope.Field, "total",
            """{ "+": [ { "var": "qty" }, { "var": "extra" } ] }""", RuleActionKind.Compute);
        var (compiled, result) = Evaluate(rule, new JsonObject { ["qty"] = 3, ["extra"] = 4 });
        var entry = RuleTraceBuilder.BuildForm(compiled, result).Single();

        Assert.Equal(RuleTraceCodes.ValueComputed, entry.Code);
        Assert.Equal("extra,qty", string.Join(",", entry.Params["reads"].Split(',').OrderBy(x => x))); // both inputs referenced
        Assert.DoesNotContain("7", string.Join("|", entry.Params.Values)); // the computed value (7) is not in the trace
    }

    [Fact]
    public void GuardTrace_PassedAndFailed_CarryCodeAndFieldRef()
    {
        var guard = RuleDefinitionFactory.Create("g.amount", RuleTier.JsonLogic, RuleScope.Schema, "",
            """{ ">": [ { "var": "amount" }, 5000 ] }""", RuleActionKind.Validate);
        var evaluator = new GuardEvaluator(TimeProvider.System);

        var pass = evaluator.EvaluateGuard(guard, RuleContextSnapshot.Capture(new Dictionary<string, JsonNode?> { ["amount"] = 7000 }), RuleEvalScope.Root, TestAdmission.Any);
        var passTrace = RuleTraceBuilder.BuildGuard(guard, pass);
        Assert.Equal(RuleTraceCodes.GuardPassed, passTrace.Code);
        Assert.Equal("amount", passTrace.Params["reads"]);
        Assert.Equal("guard:g.amount", passTrace.Target);

        var fail = evaluator.EvaluateGuard(guard, RuleContextSnapshot.Capture(new Dictionary<string, JsonNode?> { ["amount"] = 3000 }), RuleEvalScope.Root, TestAdmission.Any);
        var failTrace = RuleTraceBuilder.BuildGuard(guard, fail);
        Assert.Equal(RuleTraceCodes.GuardFailed, failTrace.Code);
        Assert.Equal("g.amount", failTrace.Params["cause"]);
        Assert.DoesNotContain("3000", string.Join("|", failTrace.Params.Values)); // never the value
    }

    private static string Fnv1aRef(string s)
    {
        const uint offset = 2166136261, prime = 16777619;
        uint h = offset;
        foreach (char c in s) { h ^= (byte)(c & 0xFF); h *= prime; h ^= (byte)((c >> 8) & 0xFF); h *= prime; }
        return h.ToString("x8");
    }

    private sealed class DenyFilter(string field) : ITraceAuthorityFilter
    {
        public TraceFieldDisclosure Disclose(string fieldName)
            => fieldName == field ? TraceFieldDisclosure.Redact : TraceFieldDisclosure.Show;
    }

    private sealed class ShredFilter(string field) : ITraceAuthorityFilter
    {
        public TraceFieldDisclosure Disclose(string fieldName)
            => fieldName == field ? TraceFieldDisclosure.Hash : TraceFieldDisclosure.Show;
    }
}

using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Compilation;
using Harborline.Foundation.RuleEngine.Skins;


using Xunit;

namespace Harborline.Foundation.RuleEngine.Tests;

/// <summary>
/// ADR 0146 D2 — decision-table + formula authoring-skin COMPILE rejections + happy-path lowering. The
/// byte-identical routing outcomes live in the shared conformance corpus (decision-table-skin.json /
/// formula-skin.json); this asserts the fail-closed rejections (which throw at compile, so cannot be corpus
/// outcome cases) and the exact lowered shape (board F1: hit policy resolved inside the compiled rule, an
/// explicit no-match, reified interval bounds).
/// </summary>
public sealed class SkinTests
{
    private static DecisionTableSkin MinimalTable(
        IReadOnlyList<string>? inputs = null,
        IReadOnlyList<DecisionRow>? rows = null,
        NoMatch? noMatch = null,
        HitPolicy policy = HitPolicy.FirstMatch)
        => new(
            RuleId: "t",
            Scope: RuleScope.Field,
            ScopeTarget: "out",
            Action: RuleActionKind.Compute,
            HitPolicy: policy,
            Inputs: inputs ?? new[] { "x" },
            Rows: rows ?? new[] { new DecisionRow(new[] { DecisionCell.Compare(">=", JsonValue.Create(1)) }, JsonValue.Create("hi")) },
            NoMatch: noMatch ?? NoMatch.WithDefault(JsonValue.Create("lo")));

    // ── decision-table rejections ────────────────────────────────────────────

    [Fact]
    public void DecisionTable_NoInputs_Rejected()
    {
        var ex = Assert.Throws<RuleCompilationException>(() => DecisionTableCompiler.Compile(MinimalTable(inputs: Array.Empty<string>())));
        Assert.Equal(SkinCodes.DecisionTableNoInputs, ex.Code);
    }

    [Fact]
    public void DecisionTable_NoRows_Rejected()
    {
        var ex = Assert.Throws<RuleCompilationException>(() => DecisionTableCompiler.Compile(MinimalTable(rows: Array.Empty<DecisionRow>())));
        Assert.Equal(SkinCodes.DecisionTableEmpty, ex.Code);
    }

    [Fact]
    public void DecisionTable_RaggedRow_Rejected()
    {
        // one input column but a row with two cells.
        var rows = new[] { new DecisionRow(new[] { DecisionCell.Wildcard, DecisionCell.Wildcard }, JsonValue.Create("x")) };
        var ex = Assert.Throws<RuleCompilationException>(() => DecisionTableCompiler.Compile(MinimalTable(rows: rows)));
        Assert.Equal(SkinCodes.DecisionTableBadRow, ex.Code);
    }

    [Fact]
    public void DecisionTable_BadCompareOp_Rejected()
    {
        var rows = new[] { new DecisionRow(new[] { DecisionCell.Compare("~=", JsonValue.Create(1)) }, JsonValue.Create("x")) };
        var ex = Assert.Throws<RuleCompilationException>(() => DecisionTableCompiler.Compile(MinimalTable(rows: rows)));
        Assert.Equal(SkinCodes.DecisionTableBadCell, ex.Code);
    }

    [Fact]
    public void DecisionTable_UnknownCellKind_RejectedWithInputNamed()
    {
        var rows = new[]
        {
            new DecisionRow(new[] { new DecisionCell((CellKind)99) }, JsonValue.Create("x")),
        };

        var ex = Assert.Throws<RuleCompilationException>(() =>
            DecisionTableCompiler.Compile(MinimalTable(inputs: new[] { "amount" }, rows: rows)));

        Assert.Equal(SkinCodes.DecisionTableBadCell, ex.Code);
        Assert.Contains("amount", ex.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void DecisionTable_NonNumericRangeBound_RejectedWithInputNamed()
    {
        var rows = new[]
        {
            new DecisionRow(
                new[] { DecisionCell.Range(JsonValue.Create("not-a-number"), null) },
                JsonValue.Create("x")),
        };

        var ex = Assert.Throws<RuleCompilationException>(() =>
            DecisionTableCompiler.Compile(MinimalTable(inputs: new[] { "amount" }, rows: rows)));

        Assert.Equal(SkinCodes.DecisionTableBadCell, ex.Code);
        Assert.Contains("amount", ex.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void DecisionTable_NoExplicitNoMatch_Rejected()
    {
        // Neither a declared default nor a catch-all → a silent null on no-match is forbidden (board F1).
        var noMatch = new NoMatch(HasDefault: false, RequireCatchAll: false);
        var ex = Assert.Throws<RuleCompilationException>(() => DecisionTableCompiler.Compile(MinimalTable(noMatch: noMatch)));
        Assert.Equal(SkinCodes.NoMatchUnresolved, ex.Code);
    }

    [Fact]
    public void DecisionTable_CatchAllRequiredButAbsent_Rejected()
    {
        // RequireCatchAll but no all-Any row present → rejected.
        var rows = new[] { new DecisionRow(new[] { DecisionCell.Compare(">=", JsonValue.Create(1)) }, JsonValue.Create("hi")) };
        var ex = Assert.Throws<RuleCompilationException>(() => DecisionTableCompiler.Compile(MinimalTable(rows: rows, noMatch: NoMatch.CatchAll)));
        Assert.Equal(SkinCodes.NoMatchUnresolved, ex.Code);
    }

    // ── decision-table happy path (exact lowered shape) ──────────────────────

    [Fact]
    public void DecisionTable_Priority_LowersToOrderedIfCascade()
    {
        // Declared order B(1), A(2); priority reorders A ahead of B; catch-all is the terminal else.
        var skin = new DecisionTableSkin(
            RuleId: "tier",
            Scope: RuleScope.Field, ScopeTarget: "tier", Action: RuleActionKind.Compute,
            HitPolicy: HitPolicy.Priority,
            Inputs: new[] { "score" },
            Rows: new[]
            {
                new DecisionRow(new[] { DecisionCell.Compare(">=", JsonValue.Create(80)) }, JsonValue.Create("B"), Priority: 1),
                new DecisionRow(new[] { DecisionCell.Compare(">=", JsonValue.Create(90)) }, JsonValue.Create("A"), Priority: 2),
                new DecisionRow(new[] { DecisionCell.Wildcard }, JsonValue.Create("F"), Priority: 0),
            },
            NoMatch: NoMatch.CatchAll);

        var rule = DecisionTableCompiler.Compile(skin);
        Assert.Equal(RuleTier.JsonLogic, rule.Tier);
        Assert.Equal(RuleActionKind.Compute, rule.Action);

        var expected = JsonNode.Parse("""
            { "if": [
              { ">=": [ { "var": "score" }, 90 ] }, "A",
              { ">=": [ { "var": "score" }, 80 ] }, "B",
              "F" ] }
            """);
        Assert.Equal(Canonical(expected), Canonical(JsonNode.Parse(rule.Expression)));
    }

    [Fact]
    public void DecisionTable_ReifiesRangeUpperBound()
    {
        var skin = MinimalTable(
            rows: new[]
            {
                new DecisionRow(new[] { DecisionCell.Range(JsonValue.Create(0), JsonValue.Create(100)) }, JsonValue.Create("in")),
            },
            noMatch: NoMatch.WithDefault(JsonValue.Create("out")));
        var rule = DecisionTableCompiler.Compile(skin);
        var expected = JsonNode.Parse("""
            { "if": [
              { "and": [ { ">=": [ { "var": "x" }, 0 ] }, { "<": [ { "var": "x" }, 100 ] } ] }, "in",
              "out" ] }
            """);
        Assert.Equal(Canonical(expected), Canonical(JsonNode.Parse(rule.Expression)));
    }

    // ── formula rejections + happy path ──────────────────────────────────────

    [Fact]
    public void Formula_EmptyExpression_Rejected()
    {
        var skin = new FormulaSkin("f", RuleScope.Field, "out", RuleActionKind.Compute, Array.Empty<FormulaInput>(), Expression: null);
        var ex = Assert.Throws<RuleCompilationException>(() => FormulaCompiler.Compile(skin));
        Assert.Equal(SkinCodes.FormulaEmpty, ex.Code);
    }

    [Fact]
    public void Formula_UndeclaredRef_Rejected()
    {
        // References `price` but only `qty` is declared.
        var expr = JsonNode.Parse("""{ "*": [ { "var": "qty" }, { "var": "price" } ] }""");
        var skin = new FormulaSkin("f", RuleScope.Field, "total", RuleActionKind.Compute,
            new[] { new FormulaInput("qty", "number") }, expr);
        var ex = Assert.Throws<RuleCompilationException>(() => FormulaCompiler.Compile(skin));
        Assert.Equal(SkinCodes.FormulaUndeclaredRef, ex.Code);
        Assert.Contains("price", ex.Message);
    }

    [Fact]
    public void Formula_DeclaredInputDoesNotCertifyRuntimeValuesItCannotGuard()
    {
        var expr = JsonNode.Parse("""{ "money.add": [ { "var": "approved" }, "1.00" ] }""");
        var skin = new FormulaSkin("f", RuleScope.Field, "total", RuleActionKind.Compute,
            new[] { new FormulaInput("approved", "boolean") }, expr);

        var rule = FormulaCompiler.Compile(skin);
        Assert.Equal(RuleActionKind.Compute, rule.Action);
    }

    [Fact]
    public void Formula_AlsoRunsTheCoreStaticAdmissionBeforeReturningARule()
    {
        var skin = new FormulaSkin("f", RuleScope.Field, "total", RuleActionKind.Compute,
            Array.Empty<FormulaInput>(), JsonNode.Parse("""{ "date.today": ["unexpected"] }"""));

        var ex = Assert.Throws<RuleCompilationException>(() => FormulaCompiler.Compile(skin));

        Assert.Equal(RuleEngineCodes.CompileInvalidExpression, ex.Code);
    }

    [Fact]
    public void Formula_AllRefsDeclared_Compiles()
    {
        var expr = JsonNode.Parse("""{ "*": [ { "var": "qty" }, { "var": "price" } ] }""");
        var skin = new FormulaSkin("f", RuleScope.Field, "total", RuleActionKind.Compute,
            new[] { new FormulaInput("qty", "number"), new FormulaInput("price", "number") }, expr);
        var rule = FormulaCompiler.Compile(skin);
        Assert.Equal(RuleActionKind.Compute, rule.Action);
        Assert.Equal(Canonical(expr), Canonical(JsonNode.Parse(rule.Expression)));
    }

    private static string Canonical(JsonNode? node)
    {
        var sb = new System.Text.StringBuilder();
        Conformance.CanonicalJson.Write(node, sb);
        return sb.ToString();
    }
}

using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Standings;

using Xunit;

namespace Harborline.Foundation.RuleEngine.Tests;

/// <summary>T-591: the platform standing rule, its store, and authorized set evaluation.</summary>
public sealed class StandingTests
{
    internal static RuleDefinition Predicate(string id, string expression)
        => RuleDefinitionFactory.Create(id, RuleTier.JsonLogic, RuleScope.Schema, "", expression, RuleActionKind.Validate);

    internal static StandingRuleDefinition Rule(string id, string standing, string expression, params string[] inputs)
        => new(id, "1.0.0", new StandingReference(standing), "asset", inputs, Predicate(id, expression));

    [Fact(DisplayName = "rules-ck-21: a standing rule is a schema-scoped validation predicate whose declared inputs name exactly the fields it reads")]
    public void Standing_rule_declares_exactly_the_fields_it_reads()
    {
        var rule = Rule("overdue", "overdue", """{">":[{"var":"daysLate"},30]}""", "daysLate");
        Assert.Equal(["daysLate"], rule.InputFields);
        Assert.Equal("overdue", rule.Standing.Name);

        // An undeclared read, an unread declaration, a non-predicate action and a mismatched id each refuse.
        Assert.Throws<ArgumentException>(() => Rule("a", "s", """{">":[{"var":"daysLate"},{"var":"grace"}]}""", "daysLate"));
        Assert.Throws<ArgumentException>(() => Rule("b", "s", """{">":[{"var":"daysLate"},30]}""", "daysLate", "grace"));
        Assert.Throws<ArgumentException>(() => new StandingRuleDefinition("c", "1.0.0", new StandingReference("s"), "asset", ["x"],
            RuleDefinitionFactory.Create("c", RuleTier.JsonLogic, RuleScope.Schema, "", """{"var":"x"}""", RuleActionKind.Compute)));
        Assert.Throws<ArgumentException>(() => new StandingRuleDefinition("d", "1.0.0", new StandingReference("s"), "asset", ["x"],
            Predicate("other", """{"var":"x"}""")));
    }

    private static readonly DateTimeOffset At = new(2026, 9, 25, 0, 0, 0, TimeSpan.Zero);

    private static StandingRecord Row(string id, string status, int amount)
        => new(id, "asset", new Dictionary<string, JsonNode?> { ["status"] = status, ["amount"] = amount, ["id"] = id });

    private static ValueTask<bool> Everyone(StandingRecord row, CancellationToken ct) => ValueTask.FromResult(true);

    [Fact(DisplayName = "rules-eng-20: 1,000 rows sharing one invariant predicate take one predicate evaluation and yield 1,000 classified outcomes; a distinct-record predicate takes 1,000 and classifies each row by its own value")]
    public async Task Standing_set_evaluation_is_sublinear_in_shared_inputs_and_exact_per_record()
    {
        // Workload stated before running: 1,000 asset rows, all status "open", amounts 0..999.
        var rows = Enumerable.Range(0, 1000).Select(i => Row("a" + i.ToString("D4", System.Globalization.CultureInfo.InvariantCulture), "open", i)).ToArray();
        var open = Rule("open", "open", """{"==":[{"var":"status"},"open"]}""", "status");
        var large = Rule("large", "large", """{">":[{"var":"amount"},500]}""", "amount");
        var evaluator = new StandingEvaluator();

        // Invariant predicate: expect exactly 1 evaluation and 1,000 classified outcomes.
        var shared = await evaluator.EvaluateSetAsync(Grants.All, rows, Everyone, [open], TestAdmission.Any, At, 0, 1000);
        Assert.Equal(1, shared.PredicateEvaluations);
        Assert.Equal(1000, shared.VisibleCount);
        Assert.Equal(1000, shared.Page.Count);
        Assert.All(shared.Page, row => Assert.Equal([new StandingReference("open")], row.Standings));
        Assert.Equal(1000, shared.Counts[new StandingReference("open")]);

        // Distinct-record predicate: a cache keyed on anything but the rule's inputs would misclassify here.
        var distinct = await evaluator.EvaluateSetAsync(Grants.All, rows, Everyone, [large], TestAdmission.Any, At, 0, 1000);
        Assert.Equal(1000, distinct.PredicateEvaluations);
        Assert.Equal(499, distinct.Counts[new StandingReference("large")]);
        Assert.Empty(distinct.Page.Single(row => row.RecordId == "a0500").Standings);
        Assert.Equal([new StandingReference("large")], distinct.Page.Single(row => row.RecordId == "a0501").Standings);

        var both = await evaluator.EvaluateSetAsync(Grants.All, rows, Everyone, [open, large], TestAdmission.Any, At, 0, 10);
        Assert.Equal(1001, both.PredicateEvaluations);
        Assert.Equal(2, both.Page[0].Decisions.Count);
    }

    [Fact(DisplayName = "rules-eng-20: interleaved unauthorized rows are removed before standing evaluation, counting and paging, so they never alter visible counts, pages or the evaluation count")]
    public async Task Unauthorized_rows_never_reach_standing_evaluation_counts_or_pages()
    {
        var authorized = Enumerable.Range(0, 1000).Select(i => Row("a" + i.ToString("D4", System.Globalization.CultureInfo.InvariantCulture), "open", i)).ToArray();
        // Each denied row carries the standing with a value no authorized row has.
        var interleaved = authorized.SelectMany((row, i) => new[] { Row("d" + i.ToString("D4", System.Globalization.CultureInfo.InvariantCulture), "open", 5000 + i), row }).ToArray();
        var large = Rule("large", "large", """{">":[{"var":"amount"},500]}""", "amount");
        var evaluator = new StandingEvaluator();
        ValueTask<bool> Access(StandingRecord row, CancellationToken ct) => ValueTask.FromResult(row.RecordId.StartsWith('a', StringComparison.Ordinal));

        var expected = await evaluator.EvaluateSetAsync(Grants.All, authorized, Everyone, [large], TestAdmission.Any, At, 490, 20);
        var actual = await evaluator.EvaluateSetAsync(Grants.All, interleaved, Access, [large], TestAdmission.Any, At, 490, 20);

        Assert.Equal(1000, actual.VisibleCount);
        Assert.Equal(expected.Counts[new StandingReference("large")], actual.Counts[new StandingReference("large")]);
        Assert.Equal(expected.Page.Select(row => row.RecordId), actual.Page.Select(row => row.RecordId));
        Assert.Equal(1000, actual.PredicateEvaluations);
    }

    [Fact(DisplayName = "rules-eng-26: standing set evaluation refuses without admission before reading any row")]
    public async Task Standing_set_evaluation_requires_admission()
    {
        var rule = Rule("open", "open", """{"==":[{"var":"status"},"open"]}""", "status");
        var result = await new StandingEvaluator().EvaluateSetAsync(Grants.All, [Row("a", "open", 1)], Everyone, [rule], null, At, 0, 10);
        var decision = Assert.Single(Assert.Single(result.Page).Decisions);
        Assert.False(decision.Carries);
        Assert.Equal(Environments.BorrowerEnvironmentAdmission.NotAdmitted, decision.RefusalCode);
    }
}

/// <summary>Host-supplied Access verdicts over capability names (test double for the host gate).</summary>
internal static class Grants
{
    public static RulesCapabilityCheck All { get; } = (_, _) => ValueTask.FromResult(true);

    public static RulesCapabilityCheck Only(params string[] granted)
        => (permission, _) => ValueTask.FromResult(granted.Contains(permission, StringComparer.Ordinal));
}

/// <summary>T-591 (owner ruling Q14): the Rules capability names and the evaluate/explain boundary.</summary>
public sealed class RulesPermissionTests
{
    private static readonly DateTimeOffset At = new(2026, 9, 25, 0, 0, 0, TimeSpan.Zero);

    [Fact(DisplayName = "rules-auth-34: Rules declares exactly four permissions, rules:author, rules:publish, rules:author-floor and rules:evaluate-explain, and seeds no role grants")]
    public void Rules_declares_its_four_capabilities()
        => Assert.Equal(["rules:author", "rules:publish", "rules:author-floor", "rules:evaluate-explain"], RulesPermissions.All);

    [Theory(DisplayName = "rules-eng-20: standing set evaluation needs both rules:evaluate-explain and records:read at the operation boundary, and refuses before any row is authorized or read")]
    [InlineData("rules:evaluate-explain")]
    [InlineData("records:read")]
    public async Task Standing_evaluation_needs_evaluate_explain_and_records_read(string only)
    {
        var rule = StandingTests.Rule("open", "open", """{"==":[{"var":"status"},"open"]}""", "status");
        var row = new StandingRecord("a", "asset", new Dictionary<string, JsonNode?> { ["status"] = "open" });
        int rowChecks = 0;
        ValueTask<bool> Count(StandingRecord record, CancellationToken ct) { rowChecks++; return ValueTask.FromResult(true); }
        var evaluator = new StandingEvaluator();

        var refused = await Assert.ThrowsAsync<RulesPermissionException>(async () =>
            await evaluator.EvaluateSetAsync(Grants.Only(only), [row], Count, [rule], TestAdmission.Any, At, 0, 10));
        Assert.Equal(RulesPermissions.DeniedCode, refused.Code);
        Assert.Equal(0, rowChecks);

        var allowed = await evaluator.EvaluateSetAsync(Grants.Only(RulesPermissions.EvaluateExplain, RulesPermissions.RecordsRead), [row], Count, [rule], TestAdmission.Any, At, 0, 10);
        Assert.Equal(1, allowed.VisibleCount);
    }

    [Theory(DisplayName = "rules-eng-19: the standing evidence read needs both rules:evaluate-explain and records:read before its own evidence-read check")]
    [InlineData("rules:evaluate-explain")]
    [InlineData("records:read")]
    public async Task Evidence_read_needs_evaluate_explain_and_records_read(string only)
    {
        var rule = StandingTests.Rule("open", "open", """{"==":[{"var":"status"},"open"]}""", "status");
        var row = new StandingRecord("a", "asset", new Dictionary<string, JsonNode?> { ["status"] = "open" });
        static ValueTask<bool> Allow(StandingRecord record, CancellationToken ct) => ValueTask.FromResult(true);
        var evaluator = new StandingEvaluator();

        Assert.Equal(StandingEvidenceAvailability.Refused,
            (await evaluator.ReadEvidenceAsync(Grants.Only(only), row, rule, Allow, TestAdmission.Any, At)).Availability);
        Assert.Equal(StandingEvidenceAvailability.Available,
            (await evaluator.ReadEvidenceAsync(Grants.Only(RulesPermissions.EvaluateExplain, RulesPermissions.RecordsRead), row, rule, Allow, TestAdmission.Any, At)).Availability);
    }
}

